CREATE TABLE "QoopProductProfile" ("id" TEXT PRIMARY KEY,"fingerprint" TEXT NOT NULL UNIQUE,"data" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "QoopPreparation" ("id" TEXT PRIMARY KEY,"fingerprint" TEXT NOT NULL UNIQUE,"designId" TEXT NOT NULL REFERENCES "Design"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"assetId" TEXT NOT NULL REFERENCES "Asset"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"profileId" TEXT REFERENCES "QoopProductProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"input" JSONB NOT NULL,"result" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "QoopPreparation_designId_createdAt_idx" ON "QoopPreparation"("designId","createdAt");
